--- a/kong.go
+++ b/kong.go
@@ -249,19 +249,19 @@ func (k *Kong) interpolateValue(value *Value, vars Vars) (err error) {
 		return fmt.Errorf("enum for %s: %s", value.Summary(), err)
 	}

-	updatedVars := map[string]string{
